package effects

import (
	"bytes"
	"encoding/binary"
	"io"
	"math"
	"runtime"
	"testing"
)

// sineSource generates a stereo L16 PCM sine wave at the given frequency and
// sample rate. Both channels get the same signal. Returns a ReadSeeker over
// the generated bytes.
func sineSource(freq float64, sampleRate int, durationSamples int) io.ReadSeeker {
	buf := make([]byte, durationSamples*4) // 4 bytes per stereo frame
	for i := 0; i < durationSamples; i++ {
		t := float64(i) / float64(sampleRate)
		val := math.Sin(2.0 * math.Pi * freq * t)
		sample := int16(val * math.MaxInt16 * 0.9)
		binary.LittleEndian.PutUint16(buf[i*4:], uint16(sample))
		binary.LittleEndian.PutUint16(buf[i*4+2:], uint16(sample))
	}
	return bytes.NewReader(buf)
}

// silenceSource returns a ReadSeeker of the given number of silent stereo frames.
func silenceSource(durationSamples int) io.ReadSeeker {
	buf := make([]byte, durationSamples*4)
	return bytes.NewReader(buf)
}

// rampWrap is the modulus of rampSource values. Half a wrap period is far
// larger than any alignment search deviation, so mod-nearest unwrapping of
// decoded values recovers absolute source frame indices.
const rampWrap = 16384

// rampSource generates stereo frames whose sample value is the frame index
// modulo rampWrap, making the source position decodable from output samples.
func rampSource(durationFrames int) io.ReadSeeker {
	buf := make([]byte, durationFrames*4)
	for i := 0; i < durationFrames; i++ {
		v := int16(i % rampWrap)
		binary.LittleEndian.PutUint16(buf[i*4:], uint16(v))
		binary.LittleEndian.PutUint16(buf[i*4+2:], uint16(v))
	}
	return bytes.NewReader(buf)
}

// readAll reads from r until EOF, returning the accumulated bytes.
func readAll(r io.Reader, bufSize int) ([]byte, error) {
	var result []byte
	buf := make([]byte, bufSize)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			result = append(result, buf[:n]...)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return result, err
		}
	}
	return result, nil
}

// leftSample decodes the left channel of stereo frame i.
func leftSample(data []byte, i int) int16 {
	return int16(binary.LittleEndian.Uint16(data[i*4:]))
}

// estimateFreqZC estimates the dominant frequency of the left channel from
// zero crossings, skipping the first skipFrames frames.
func estimateFreqZC(data []byte, sampleRate, skipFrames int) float64 {
	totalFrames := len(data) / 4
	if totalFrames <= skipFrames+1 {
		return 0
	}
	crossings := 0
	prev := leftSample(data, skipFrames)
	for i := skipFrames + 1; i < totalFrames; i++ {
		s := leftSample(data, i)
		if (prev >= 0 && s < 0) || (prev < 0 && s >= 0) {
			crossings++
		}
		prev = s
	}
	dur := float64(totalFrames-skipFrames) / float64(sampleRate)
	return float64(crossings) / (2.0 * dur)
}

// maxAdjacentStep returns the largest absolute left-channel sample-to-sample
// step in frames [fromFrame, toFrame).
func maxAdjacentStep(data []byte, fromFrame, toFrame int) int {
	totalFrames := len(data) / 4
	if toFrame > totalFrames {
		toFrame = totalFrames
	}
	maxStep := 0
	for i := fromFrame + 1; i < toFrame; i++ {
		d := int(leftSample(data, i)) - int(leftSample(data, i-1))
		if d < 0 {
			d = -d
		}
		if d > maxStep {
			maxStep = d
		}
	}
	return maxStep
}

// sineMaxSlope returns the theoretical max sample-to-sample step of the
// sineSource waveform (amplitude 0.9 * MaxInt16) at the given frequency.
func sineMaxSlope(freq float64, sampleRate int) float64 {
	return 0.9 * math.MaxInt16 * 2.0 * math.Pi * freq / float64(sampleRate)
}

func TestTimeStretch_PassthroughAt1x(t *testing.T) {
	const sampleRate = 44100
	const duration = 4410 // 0.1 seconds

	src := sineSource(440, sampleRate, duration)

	// Read the raw source data
	rawData, err := readAll(src, 4096)
	if err != nil {
		t.Fatal(err)
	}

	// Reset source
	src.Seek(0, io.SeekStart)

	// Read through TimeStretch at speed 1.0
	ts := NewTimeStretch().SetSource(src).SetSpeed(1.0)
	tsData, err := readAll(ts, 4096)
	if err != nil {
		t.Fatal(err)
	}

	if len(tsData) != len(rawData) {
		t.Fatalf("passthrough length mismatch: got %d, want %d", len(tsData), len(rawData))
	}

	if !bytes.Equal(tsData, rawData) {
		t.Error("passthrough output does not match source at speed 1.0")
	}
}

func TestTimeStretch_PassthroughWhenInactive(t *testing.T) {
	const sampleRate = 44100
	const duration = 4410

	src := sineSource(440, sampleRate, duration)

	rawData, err := readAll(src, 4096)
	if err != nil {
		t.Fatal(err)
	}

	src.Seek(0, io.SeekStart)

	// Set speed != 1.0 but inactive — should passthrough
	ts := NewTimeStretch().SetSource(src).SetSpeed(0.5).SetActive(false)
	tsData, err := readAll(ts, 4096)
	if err != nil {
		t.Fatal(err)
	}

	if !bytes.Equal(tsData, rawData) {
		t.Error("inactive TimeStretch should pass through source data unchanged")
	}
}

func TestTimeStretch_DurationScaling_SlowDown(t *testing.T) {
	const sampleRate = 44100
	const duration = 44100 // 1 second

	src := sineSource(440, sampleRate, duration)
	sourceBytes := duration * 4

	ts := NewTimeStretch().SetSource(src).SetSpeed(0.5)
	tsData, err := readAll(ts, 4096)
	if err != nil {
		t.Fatal(err)
	}

	// At 0.5x speed, output should be approximately 2x the source length.
	// Slack: 3% plus one max-length sequence (the EOF tail is emitted
	// verbatim rather than stretched).
	expectedLen := sourceBytes * 2
	seqMaxBytes := ts.msToFrames(ts.seqMaxMS) * 4
	tolerance := float64(expectedLen)*0.03 + float64(seqMaxBytes)

	diff := math.Abs(float64(len(tsData)) - float64(expectedLen))
	if diff > tolerance {
		t.Errorf("0.5x speed: expected ~%d bytes (±%.0f), got %d bytes (diff=%.0f)",
			expectedLen, tolerance, len(tsData), diff)
	}
}

