func TestTimeStretch_SpeedChangeMidStream(t *testing.T) {
	const sampleRate = 44100
	const duration = 44100

	src := sineSource(440, sampleRate, duration)
	ts := NewTimeStretch().SetSource(src).SetSpeed(0.75)

	// Read some data at 0.75x
	buf := make([]byte, 8192)
	n1, err := ts.Read(buf)
	if err != nil {
		t.Fatalf("first Read failed: %v", err)
	}
	if n1 == 0 {
		t.Fatal("first Read returned 0 bytes")
	}

	// Change speed mid-stream — should not panic
	ts.SetSpeed(1.5)

	n2, err := ts.Read(buf)
	if err != nil && err != io.EOF {
		t.Fatalf("Read after speed change failed: %v", err)
	}
	if n2 == 0 {
		t.Error("Read after speed change returned 0 bytes")
	}
}

func TestTimeStretch_NilSource(t *testing.T) {
	ts := NewTimeStretch()
	buf := make([]byte, 4096)

	n, err := ts.Read(buf)
	if n != 0 || err != io.EOF {
		t.Errorf("nil source: expected (0, EOF), got (%d, %v)", n, err)
	}
}

func TestTimeStretch_SpeedClamping(t *testing.T) {
	ts := NewTimeStretch()

	ts.SetSpeed(0.1)
	if ts.Speed() != 0.25 {
		t.Errorf("speed below minimum: got %f, want 0.25", ts.Speed())
	}

	ts.SetSpeed(5.0)
	if ts.Speed() != 4.0 {
		t.Errorf("speed above maximum: got %f, want 4.0", ts.Speed())
	}

	ts.SetSpeed(1.0)
	if ts.Speed() != 1.0 {
		t.Errorf("normal speed: got %f, want 1.0", ts.Speed())
	}
}

func TestTimeStretch_ApplyEffectIsNoop(t *testing.T) {
	ts := NewTimeStretch()

	data := []byte{0x10, 0x20, 0x30, 0x40}
	original := make([]byte, len(data))
	copy(original, data)

	ts.ApplyEffect(data, len(data))

	if !bytes.Equal(data, original) {
		t.Error("ApplyEffect modified data; it should be a no-op")
	}
}

func TestTimeStretch_CloneProducesIndependentCopy(t *testing.T) {
	ts := NewTimeStretch().SetSpeed(0.5).SetQuality(QualityHigh).SetActive(false)

	cloned := ts.Clone().(*TimeStretch)

	if cloned.Speed() != ts.Speed() {
		t.Errorf("clone speed: got %f, want %f", cloned.Speed(), ts.Speed())
	}
	if cloned.Quality() != ts.Quality() {
		t.Errorf("clone quality: got %d, want %d", cloned.Quality(), ts.Quality())
	}
	if cloned.Active() != ts.Active() {
		t.Errorf("clone active: got %v, want %v", cloned.Active(), ts.Active())
	}
	if cloned.overlap != ts.overlap || cloned.seekRadius != ts.seekRadius {
		t.Errorf("clone parameters: got %d/%d, want %d/%d",
			cloned.overlap, cloned.seekRadius, ts.overlap, ts.seekRadius)
	}

	// Changing clone should not affect original
	cloned.SetSpeed(2.0)
	if ts.Speed() == cloned.Speed() {
		t.Error("changing clone speed affected original")
	}
}

func TestTimeStretch_GettersSetters(t *testing.T) {
	ts := NewTimeStretch()

	ts.SetActive(false)
	if ts.Active() {
		t.Error("SetActive(false) did not work")
	}
	ts.SetActive(true)
	if !ts.Active() {
		t.Error("SetActive(true) did not work")
	}

	ts.SetQuality(QualityHigh)
	if ts.Quality() != QualityHigh {
		t.Errorf("Quality: got %d, want %d", ts.Quality(), QualityHigh)
	}

	ts.SetSpeed(1.5)
	if ts.Speed() != 1.5 {
		t.Errorf("Speed: got %f, want 1.5", ts.Speed())
	}
}
